cd /root/bluebot_v2 && E="Keep her face exactly as beautiful as in the sheet: young, smooth clear skin, light brown-green eyes, calm expression. Keep the costume: green layered robe, brown hooded cloak, dark brown curly hair with small white flowers, brown leather herb belt with pouches and glass vials, leather vambraces, brown boots. For a game model: the robe ends just above the ankles with no train and does not touch the floor, a little narrower so the boots show; the cloak ends at the hips; all fabric opaque, nothing see-through. Hands open and empty: fingers relaxed and slightly apart, palms toward the thighs. Leave out the bow, the quiver, the arrows, the dagger and the cheetah completely." && for V in front back; do ONLY=melika VIEW=$V EDIT="$E" ./.venv/bin/python /root/bw_art/cast3d.py; done
